modelExamples.before:
// "Remove an item from the cart" — defined so that an absent item
// is an error. Every caller now owns that error.
public class ShoppingCart
{
    private readonly List<string> _items = new();

    public void Add(string sku) => _items.Add(sku);

    public void RemoveItem(string sku)
    {
        if (!_items.Remove(sku))
        {
            throw new InvalidOperationException(
                $"Item {sku} is not in the cart.");
        }
    }
}

// One caller, doing what every caller must now do:
public class RejectedItemSweeper
{
    public void Sweep(ShoppingCart cart, IEnumerable<string> rejected)
    {
        foreach (var sku in rejected)
        {
            try
            {
                cart.RemoveItem(sku);
            }
            catch (InvalidOperationException)
            {
                // Already absent — which is exactly what we wanted.
            }
        }
    }
}

// A catch block whose comment says "this is what we wanted" is a
// contract confessing it was defined wrong.

modelExamples.after:
// The same operation, redefined: "ensure the item is absent."
// Removing what is not there is success, not an error — the error
// case no longer exists, so no caller can mishandle it.
public class ShoppingCart
{
    private readonly List<string> _items = new();

    public void Add(string sku) => _items.Add(sku);

    // Ensures no copy of the sku remains in the cart. Already
    // absent: nothing to do, and that is a successful outcome.
    public void Remove(string sku)
    {
        _items.RemoveAll(item => item == sku);
    }
}

// The same caller, with nothing left to handle:
public class RejectedItemSweeper
{
    public void Sweep(ShoppingCart cart, IEnumerable<string> rejected)
    {
        foreach (var sku in rejected)
        {
            cart.Remove(sku);
        }
    }
}

// The catch block did not move somewhere better — it ceased to
// exist, in this caller and in every other, because the condition
// it handled is no longer an error anywhere.

modelExamples.before:
// "Out of stock" is an everyday outcome for a shop — and here it is
// an exception, so the everyday branch lives in a catch block.
public class StockRoom
{
    private readonly Dictionary<string, int> _onHand = new();

    public void Receive(string sku, int count) =>
        _onHand[sku] = OnHand(sku) + count;

    public int OnHand(string sku) =>
        _onHand.TryGetValue(sku, out var count) ? count : 0;

    public void Reserve(string sku)
    {
        if (OnHand(sku) == 0)
        {
            throw new OutOfStockException(sku);
        }
        _onHand[sku] -= 1;
    }
}

// Every caller branches on the everyday outcome — via catch:
public class OrderLine
{
    public string Add(StockRoom stock, string sku)
    {
        try
        {
            stock.Reserve(sku);
            return "Reserved.";
        }
        catch (OutOfStockException)
        {
            return "Back-ordered.";
        }
    }
}

modelExamples.after:
// The outcome the caller must branch on now lives in the return
// value, where the compiler makes the branch visible and cheap.
public class StockRoom
{
    private readonly Dictionary<string, int> _onHand = new();

    public void Receive(string sku, int count) =>
        _onHand[sku] = OnHand(sku) + count;

    public int OnHand(string sku) =>
        _onHand.TryGetValue(sku, out var count) ? count : 0;

    // True and one unit reserved, or false when none is on hand —
    // an ordinary answer to an ordinary question.
    public bool TryReserve(string sku)
    {
        if (OnHand(sku) == 0) return false;
        _onHand[sku] -= 1;
        return true;
    }
}

// The everyday branch is an if, not a catch:
public class OrderLine
{
    public string Add(StockRoom stock, string sku)
    {
        return stock.TryReserve(sku) ? "Reserved." : "Back-ordered.";
    }
}

// Exception machinery is still there for what is exceptional.
// Being out of stock is not exceptional; it is Tuesday.

modelExamples.before:
// The report store lets the transient fault escape — so the retry
// loop is copied into every caller that has learned the hard way.
public class ReportStore
{
    private readonly INetworkDrive _drive;

    public ReportStore(INetworkDrive drive) => _drive = drive;

    // Throws DriveBusyException whenever the drive hiccups.
    public string Load(string reportName) => _drive.Read(reportName);
}

// Caller one — with its private copy of the retry policy:
public class MonthlyDigest
{
    public string Summary(ReportStore store)
    {
        for (var attempt = 1; ; attempt++)
        {
            try
            {
                return store.Load("monthly-summary");
            }
            catch (DriveBusyException) when (attempt < 3)
            {
                // Transient — wait a beat and go around again.
            }
        }
    }
}

// Caller two retries twice, caller three not at all, caller four
// forgot entirely and crashes on busy days: one fault, four
// policies, none of them owned by the class that knows the drive.

modelExamples.after:
// The store knows the fault is transient and what retrying costs —
// so the store handles it. The fault still happens; it is just no
// longer anyone else's problem.
public class ReportStore
{
    private const int Attempts = 3;
    private readonly INetworkDrive _drive;

    public ReportStore(INetworkDrive drive) => _drive = drive;

    public string Load(string reportName)
    {
        for (var attempt = 1; ; attempt++)
        {
            try
            {
                return _drive.Read(reportName);
            }
            catch (DriveBusyException) when (attempt < Attempts)
            {
                // Transient — wait a beat and go around again.
            }
        }
    }
}

// Every caller, from now on:
public class MonthlyDigest
{
    public string Summary(ReportStore store)
    {
        return store.Load("monthly-summary");
    }
}

// One retry policy, owned by the one class that understands the
// drive — the fault masked where the knowledge to handle it lives.

exercises.targetInterfaceCode:
public interface ISeatMap
{
    // Puts the seat on sale; call once per seat.
    void AddSeat(string seatId);

    // Reserves the seat for the customer. False — and nothing is
    // recorded — when the seat is unknown, already reserved, or the
    // customer already holds 4 reservations.
    bool Reserve(string seatId, string customerId);

    // Frees the seat. False when the seat is unknown or not
    // reserved.
    bool Release(string seatId);

    // Seats on sale and not reserved right now.
    int FreeSeatCount();
}

public interface IPlayQueue
{
    // Adds the track to the end of the queue. Queuing a track that
    // is already waiting moves it to the end instead of duplicating
    // it — asking twice is a preference, not a fault.
    void Queue(string track);

    // Removes and returns the next track, or "" (silence) when the
    // queue is empty. An empty queue is a normal state, not an
    // error.
    string PlayNext();

    // Ensures the track is not in the queue. Dropping a track that
    // was never queued is a successful no-op.
    void Drop(string track);

    // Tracks waiting right now.
    int Length();
}
